    private void btnMarcarRevisadoActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnMarcarRevisadoActionPerformed
        
String folioTexto = txtFolio.getText().trim();

if (!folioTexto.matches("\\d{4}")) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Escribe un folio de cuatro dígitos.");
    return;
}

int folio = Integer.parseInt(folioTexto);
java.io.File archivo = new java.io.File("revisiones.txt");

try (java.io.RandomAccessFile fichero =
        new java.io.RandomAccessFile(archivo, "rw")) {

    long posicion = (folio - 1) * 13L + 11;

    if (posicion >= fichero.length()) {
        javax.swing.JOptionPane.showMessageDialog(this,
                "No existe ese folio.");
        return;
    }

    fichero.seek(posicion);

    int estado = fichero.read();

    if (estado == 'P') {
        fichero.seek(posicion);
        fichero.write('R');

        javax.swing.JOptionPane.showMessageDialog(this,
                "Equipo marcado como revisado.");
    } else if (estado == 'R') {
        javax.swing.JOptionPane.showMessageDialog(this,
                "Ese equipo ya está revisado.");
    } else {
        javax.swing.JOptionPane.showMessageDialog(this,
                "El archivo no tiene el formato esperado.");
    }

    txtRegistros.setText("");
    
} catch (java.io.IOException e) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Error al actualizar: " + e.getMessage());
}

    }//GEN-LAST:event_btnMarcarRevisadoActionPerformed

    private void btnBuscarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnBuscarActionPerformed
        
String folioBuscado = txtFolio.getText().trim();
java.io.File archivo = new java.io.File("revisiones.txt");
boolean encontrado = false;

if (folioBuscado.isEmpty()) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Escribe el folio que deseas buscar.");
    return;
}

try (java.util.Scanner lector = new java.util.Scanner(archivo)) {
    while (lector.hasNextLine()) {
        String linea = lector.nextLine();

        if (linea.startsWith(folioBuscado + "|")) {
            txtRegistros.setText(linea);
            encontrado = true;
            break;
        }
    }

    if (!encontrado) {
        txtRegistros.setText("No se encontró el folio " + folioBuscado);
    }

} catch (java.io.FileNotFoundException e) {
    txtRegistros.setText("No existe el archivo revisiones.txt");
}

    }//GEN-LAST:event_btnBuscarActionPerformed

