    private void btnMostrarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnMostrarActionPerformed
        
java.io.File archivo = new java.io.File("revisiones.txt");

try (java.util.Scanner lector = new java.util.Scanner(archivo)) {
    String registros = "";

    while (lector.hasNextLine()) {
        registros += lector.nextLine() + "\n";
    }

    txtRegistros.setText(registros);

} catch (java.io.FileNotFoundException e) {
    txtRegistros.setText("No existe el archivo revisiones.txt");
}

    }//GEN-LAST:event_btnMostrarActionPerformed

    private void btnRegistrarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnRegistrarActionPerformed
        
String codigo = txtCodigoEquipo.getText().trim();

    if (!codigo.matches("[A-Za-z0-9]{5}")) {
        javax.swing.JOptionPane.showMessageDialog(this,
                "El código debe tener 5 caracteres alfanuméricos.");
        return;
    }

    java.io.File archivo = new java.io.File("revisiones.txt");
    int folio = 1;

    try {
        if (archivo.exists()) {
            try (java.util.Scanner lector = new java.util.Scanner(archivo)) {
                while (lector.hasNextLine()) {
                    lector.nextLine();
                    folio++;
                }
            }
        }

        if (folio > 9999) {
            javax.swing.JOptionPane.showMessageDialog(this,
                    "No se pueden registrar más equipos.");
            return;
        }

        String registro = String.format("%04d|%s|P\n", folio, codigo);

        try (java.io.FileOutputStream escritor =
                new java.io.FileOutputStream(archivo, true)) {
            escritor.write(registro.getBytes(
                    java.nio.charset.StandardCharsets.US_ASCII));
        }

        txtFolio.setText(String.format("%04d", folio));
        txtCodigoEquipo.setText("");

        javax.swing.JOptionPane.showMessageDialog(this,
                "Equipo registrado correctamente.");

    } catch (java.io.IOException e) {
        javax.swing.JOptionPane.showMessageDialog(this,
                "Error al registrar: " + e.getMessage());
    }



    }//GEN-LAST:event_btnRegistrarActionPerformed

